156	            throw new Xxd47Exception("구매자 이메일이 없습니다.");
157	        }
158	        if (saleBidId == null) {
159	            throw new Xkt44Exception("판매 입찰 ID가 없습니다.");
160	        }
161	        if (addressId == null) {
162	            throw new Xnb95Exception("배송지 ID가 없습니다.");
163	        }
164	        if (paymentRequest == null) {
